/*
 * Pyromancer — painted artwork (SS.Art).
 *
 * Paintings are optional: the game shows an icon wherever a painting is missing, so
 * artwork can be added a few pieces at a time. Which paintings exist is listed in
 * js/ui/art-manifest.js (SS.ART), generated by `python3 tools/art.py` from the images
 * in assets/art/source/ — see docs/ART-PROMPTS.md for what each slot should show.
 *
 *   SS.Art.get("location-tower")  → { src, width, height } or null
 *   SS.Art.portrait("ada")        → image URL or null   (slot "portrait-ada")
 *   SS.Art.location("tower")      → image URL or null   (slot "location-tower")
 *   SS.Art.extra("map")           → image URL or null   (slot "map")
 */
(function (global) {
  "use strict";
  var SS = (global.SS = global.SS || {});

  var SLOTS = {
    portraits: ["ada", "pip", "glitch", "hydra"],
    locations: ["tower", "hall", "circle", "library", "workshop", "labyrinth", "hydra"],
    extras: ["map", "ending"]
  };

  function get(key) {
    var manifest = SS.ART || {};
    var entry = Object.prototype.hasOwnProperty.call(manifest, key) ? manifest[key] : null;
    return entry && typeof entry.src === "string" ? entry : null;
  }

  function url(key) {
    var entry = get(key);
    return entry ? entry.src : null;
  }

  SS.Art = {
    SLOTS: SLOTS,
    get: get,
    url: url,
    has: function (key) { return !!get(key); },
    portrait: function (characterId) { return url("portrait-" + characterId); },
    location: function (chapterId) { return url("location-" + chapterId); },
    extra: function (name) { return url(name); }
  };
})(typeof window !== "undefined" ? window : globalThis);
